package com.dukaops.backend.settings;
import org.springframework.http.HttpStatus; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import com.dukaops.backend.auth.*; import com.dukaops.backend.settings.dto.*;
@Service public class ProfileService { private final TenantUserRepository users; private final PasswordEncoder encoder; public ProfileService(TenantUserRepository u,PasswordEncoder e){users=u;encoder=e;} private TenantUser user(TenantUserPrincipal p){return users.findTenantScopedUserById(p.getUserId(),p.getTenantId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Profile not found."));} private ProfileResponse response(TenantUser u){return new ProfileResponse(u.getId(),u.getFullName(),u.getEmail(),u.getRole().name(),u.getStatus().name(),u.getCreatedAt(),u.getUpdatedAt());} @Transactional(readOnly=true) public ProfileResponse get(TenantUserPrincipal p){return response(user(p));} @Transactional public ProfileResponse update(TenantUserPrincipal p,ProfileRequest r){TenantUser u=user(p);u.updateFullName(r.fullName().trim());return response(u);} @Transactional public void password(TenantUserPrincipal p,ChangePasswordRequest r){TenantUser u=user(p);if(!encoder.matches(r.currentPassword(),u.getPasswordHash()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Current password is incorrect.");if(encoder.matches(r.newPassword(),u.getPasswordHash()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"New password must be different from the current password.");u.changePassword(encoder.encode(r.newPassword()));}}
